<script setup lang="ts">
import { formatEuro } from '#fsd/shared/lib'
import { MoneyInput, PageHeader, EmptyState, StatusBadge, DeleteConfirmModal } from '#fsd/shared/ui'
import { useCurrentUser } from '#fsd/shared/auth'

const currentUser = useCurrentUser()
if (!currentUser.value?.roles.includes('administrator')) await navigateTo('/')
type Service = { id: string; name: string; priceEur: number; managerSharePercent: number; active: boolean }
const { data: services, refresh, status } = await useAsyncData('settings-services', () => $fetch<Service[]>('/api/special-services'))
const open = ref(false); const pending = ref(false); const error = ref('')
const serviceToEdit = ref<Service | null>(null); const serviceToDelete = ref<Service | null>(null); const deleteOpen = ref(false); const deletePending = ref(false)
const form = reactive({ name: '', priceEur: 0 as number | null, managerSharePercent: 0, active: true })
function resetForm() { Object.assign(form, { name: '', priceEur: 0, managerSharePercent: 0, active: true }) }
function openCreate() { serviceToEdit.value = null; resetForm(); error.value = ''; open.value = true }
function openEdit(service: Service) { serviceToEdit.value = service; Object.assign(form, service); error.value = ''; open.value = true }
async function save() { pending.value = true; error.value = ''; try { await $fetch(serviceToEdit.value ? `/api/special-services/${serviceToEdit.value.id}` : '/api/special-services', { method: serviceToEdit.value ? 'PATCH' : 'POST', body: form }); open.value = false; serviceToEdit.value = null; resetForm(); await refresh() } catch (cause: any) { error.value = cause?.data?.statusMessage ?? (serviceToEdit.value ? 'Не удалось изменить услугу' : 'Не удалось создать услугу') } finally { pending.value = false } }
async function toggle(service: Service) { await $fetch(`/api/special-services/${service.id}`, { method: 'PATCH', body: { name: service.name, priceEur: service.priceEur, managerSharePercent: service.managerSharePercent, active: !service.active } }); await refresh() }
function askToDelete(service: Service) { serviceToDelete.value = service; error.value = ''; deleteOpen.value = true }
async function removeService() { if (!serviceToDelete.value) return; deletePending.value = true; error.value = ''; try { await $fetch(`/api/special-services/${serviceToDelete.value.id}`, { method: 'DELETE' }); deleteOpen.value = false; serviceToDelete.value = null; await refresh() } catch (cause: any) { error.value = cause?.data?.statusMessage ?? 'Не удалось удалить услугу' } finally { deletePending.value = false } }
</script>

<template><section class="page-wrap space-y-6"><PageHeader title="Дополнительные услуги" description="Услуги, которые можно добавить к заезду."><template #actions><UButton icon="i-lucide-plus" @click="openCreate">Добавить услугу</UButton></template></PageHeader><div v-if="status === 'pending'" class="grid gap-3"><USkeleton v-for="item in 3" :key="item" class="h-20 rounded-2xl" /></div><div v-else-if="services?.length" class="surface divide-y divide-[var(--color-line)] px-5 sm:px-6"><div v-for="service in services" :key="service.id" class="flex min-h-20 items-center gap-4 py-4"><div class="min-w-0 flex-1"><div class="flex items-center gap-2"><p class="truncate font-semibold">{{ service.name }}</p><StatusBadge :label="service.active ? 'Активна' : 'Отключена'" :tone="service.active ? 'success' : 'neutral'" /></div><p class="mt-1 text-sm text-[var(--color-muted)]">Доля управляющего — {{ service.managerSharePercent }}%</p></div><p class="font-semibold tabular-nums">{{ formatEuro(service.priceEur) }}</p><div class="flex items-center gap-1"><UButton color="neutral" variant="ghost" class="min-h-11 active:scale-[0.96] transition-transform" @click="toggle(service)">{{ service.active ? 'Отключить' : 'Включить' }}</UButton><UButton color="neutral" variant="ghost" icon="i-lucide-pencil" aria-label="Изменить услугу" class="min-h-11 min-w-11 active:scale-[0.96] transition-transform" @click="openEdit(service)" /><UButton color="error" variant="ghost" icon="i-lucide-trash-2" aria-label="Удалить услугу" class="min-h-11 min-w-11 active:scale-[0.96] transition-transform" @click="askToDelete(service)" /></div></div></div><EmptyState v-else icon="i-lucide-concierge-bell" title="Услуг пока нет" description="Добавьте трансфер, поздний выезд или другую услугу для гостей." /><USlideover v-model:open="open" :title="serviceToEdit ? 'Изменить услугу' : 'Новая услуга'"><template #body><form class="form-grid" @submit.prevent="save"><UFormField label="Название"><UInput v-model="form.name" placeholder="Например, поздний выезд" required /></UFormField><UFormField label="Цена"><MoneyInput v-model="form.priceEur" required /></UFormField><UFormField label="Доля управляющего, %"><UInput v-model.number="form.managerSharePercent" type="number" min="0" max="100" required /></UFormField><UCheckbox v-model="form.active" label="Услуга доступна для новых заездов" /><UAlert v-if="error && !deleteOpen" color="error" variant="soft" :description="error" /><div class="form-actions"><UButton color="neutral" variant="ghost" @click="open = false">Отмена</UButton><UButton type="submit" :loading="pending">{{ serviceToEdit ? 'Сохранить изменения' : 'Добавить услугу' }}</UButton></div></form></template></USlideover><DeleteConfirmModal v-model:open="deleteOpen" title="Удалить дополнительную услугу" :description="`Услуга «${serviceToDelete?.name ?? ''}» будет удалена навсегда. Она исчезнет из всех заездов, где была выбрана, вместе со связанными финансовыми записями. Сами заезды сохранятся.`" :loading="deletePending" :error="error" @confirm="removeService" /></section></template>
